package com.parkcontrol.features.agreements.data.local.dao

import androidx.room.Dao
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.Query
import androidx.room.Update
import com.parkcontrol.features.agreements.data.local.entity.AgreementEntity

@Dao
interface AgreementDao {

    @Query("SELECT * FROM agreements WHERE id = :id LIMIT 1")
    suspend fun getAgreementById(id: Int): AgreementEntity?

    @Insert(onConflict = OnConflictStrategy.ABORT)
    suspend fun insertAgreement(agreement: AgreementEntity): Long

    @Update
    suspend fun updateAgreement(agreement: AgreementEntity)
}

package com.parkcontrol.features.agreements.data.local.dao

import androidx.room.Dao
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.Query
import androidx.room.Update
import com.parkcontrol.features.agreements.data.local.entity.AgreementEntity
import kotlinx.coroutines.flow.Flow

@Dao
interface AgreementDao {

    @Query("SELECT * FROM agreements WHERE isActive = 1 ORDER BY id DESC")
    fun observeActiveAgreements(): Flow<List<AgreementEntity>>

    @Query("SELECT * FROM agreements WHERE isActive = 0 ORDER BY id DESC")
    fun observeInactiveAgreements(): Flow<List<AgreementEntity>>

    @Query("SELECT * FROM agreements WHERE id = :id LIMIT 1")
    suspend fun getAgreementById(id: Int): AgreementEntity?

    @Insert(onConflict = OnConflictStrategy.ABORT)
    suspend fun insertAgreement(agreement: AgreementEntity): Long

    @Update
    suspend fun updateAgreement(agreement: AgreementEntity)

    @Query("UPDATE agreements SET isActive = 0, updatedAt = :updatedAt WHERE id = :agreementId")
    suspend fun inactivateAgreement(agreementId: Int, updatedAt: Long)

    @Query("UPDATE agreements SET isActive = 1, updatedAt = :updatedAt WHERE id = :agreementId")
    suspend fun activateAgreement(agreementId: Int, updatedAt: Long)
}

package com.parkcontrol.features.agreements.data.local.entity
import androidx.room.Entity import androidx.room.PrimaryKey
@Entity(tableName = "agreements") data class AgreementEntity( @PrimaryKey(autoGenerate = true) val id: Int = 0, val name: String, val contactName: String, val phone: String, val email: String, val street: String, val number: String, val complement: String, val city: String, val neighborhood: String, val state: String, val zipCode: String, val discountCents: Int, val createdAt: Long, val updatedAt: Long )

package com.parkcontrol.features.agreements.data.local.entity
import androidx.room.Entity import androidx.room.PrimaryKey
@Entity(tableName = "agreements") data class AgreementEntity( @PrimaryKey(autoGenerate = true) val id: Int = 0, val name: String, val contactName: String, val phone: String, val email: String, val street: String, val number: String, val complement: String, val city: String, val neighborhood: String, val state: String, val zipCode: String, val discountCents: Int, val isActive: Boolean = true, val createdAt: Long, val updatedAt: Long )

package com.parkcontrol.features.agreements.data.local.mapper
import com.parkcontrol.features.agreements.data.local.entity.AgreementEntity import com.parkcontrol.features.agreements.domain.model.Agreement
fun AgreementEntity.toDomain(): Agreement { return Agreement( id = id, name = name, contactName = contactName, phone = phone, email = email, street = street, number = number, complement = complement, city = city, neighborhood = neighborhood, state = state, zipCode = zipCode, discountCents = discountCents, createdAt = createdAt, updatedAt = updatedAt ) }
fun Agreement.toEntity(): AgreementEntity { return AgreementEntity( id = id, name = name, contactName = contactName, phone = phone, email = email, street = street, number = number, complement = complement, city = city, neighborhood = neighborhood, state = state, zipCode = zipCode, discountCents = discountCents, createdAt = createdAt, updatedAt = updatedAt ) }

package com.parkcontrol.features.agreements.data.local.mapper
import com.parkcontrol.features.agreements.data.local.entity.AgreementEntity import com.parkcontrol.features.agreements.domain.model.Agreement
fun AgreementEntity.toDomain(): Agreement { return Agreement( id = id, name = name, contactName = contactName, phone = phone, email = email, street = street, number = number, complement = complement, city = city, neighborhood = neighborhood, state = state, zipCode = zipCode, discountCents = discountCents, isActive = isActive, createdAt = createdAt, updatedAt = updatedAt ) }
fun Agreement.toEntity(): AgreementEntity { return AgreementEntity( id = id, name = name, contactName = contactName, phone = phone, email = email, street = street, number = number, complement = complement, city = city, neighborhood = neighborhood, state = state, zipCode = zipCode, discountCents = discountCents, isActive = isActive, createdAt = createdAt, updatedAt = updatedAt ) }

package com.parkcontrol.features.agreements.data.repository

import com.parkcontrol.features.agreements.data.local.dao.AgreementDao
import com.parkcontrol.features.agreements.data.local.mapper.toDomain
import com.parkcontrol.features.agreements.data.local.mapper.toEntity
import com.parkcontrol.features.agreements.domain.model.Agreement
import com.parkcontrol.features.agreements.domain.repository.AgreementRepository

class AgreementRepositoryImpl(
    private val dao: AgreementDao
) : AgreementRepository {

    override suspend fun getAgreementById(id: Int): Agreement? {
        return dao.getAgreementById(id)?.toDomain()
    }

    override suspend fun addAgreement(agreement: Agreement): Int {
        return dao.insertAgreement(agreement.copy(id = 0).toEntity()).toInt()
    }

    override suspend fun updateAgreement(agreement: Agreement) {
        dao.updateAgreement(agreement.toEntity())
    }
}

package com.parkcontrol.features.agreements.data.repository

import com.parkcontrol.features.agreements.data.local.dao.AgreementDao
import com.parkcontrol.features.agreements.data.local.mapper.toDomain
import com.parkcontrol.features.agreements.data.local.mapper.toEntity
import com.parkcontrol.features.agreements.domain.model.Agreement
import com.parkcontrol.features.agreements.domain.repository.AgreementRepository
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.map

class AgreementRepositoryImpl(
    private val dao: AgreementDao
) : AgreementRepository {

    override fun observeActiveAgreements(): Flow<List<Agreement>> {
        return dao.observeActiveAgreements().map { entities -> entities.map { it.toDomain() } }
    }

    override fun observeInactiveAgreements(): Flow<List<Agreement>> {
        return dao.observeInactiveAgreements().map { entities -> entities.map { it.toDomain() } }
    }

    override suspend fun getAgreementById(id: Int): Agreement? {
        return dao.getAgreementById(id)?.toDomain()
    }

    override suspend fun addAgreement(agreement: Agreement): Int {
        return dao.insertAgreement(agreement.copy(id = 0).toEntity()).toInt()
    }

    override suspend fun updateAgreement(agreement: Agreement) {
        dao.updateAgreement(agreement.toEntity())
    }

    override suspend fun inactivateAgreement(id: Int) {
        dao.inactivateAgreement(agreementId = id, updatedAt = System.currentTimeMillis())
    }

    override suspend fun activateAgreement(id: Int) {
        dao.activateAgreement(agreementId = id, updatedAt = System.currentTimeMillis())
    }
}

package com.parkcontrol.features.monthlyCustomers.data.local.entity
import androidx.room.Entity import androidx.room.PrimaryKey
@Entity(tableName = "monthly_customers") data class MonthlyCustomerEntity( @PrimaryKey(autoGenerate = true) val id: Int = 0, val name: String, val phone: String, val email: String, val isMonthly: Boolean = true, val monthlyFeeCents: Int? = null, val dueDay: Int? = null, val isActive: Boolean = true, val createdAt: Long, val updatedAt: Long )

package com.parkcontrol.features.monthlyCustomers.data.local.entity
import androidx.room.Entity import androidx.room.PrimaryKey
@Entity(tableName = "monthly_customers") data class MonthlyCustomerEntity( @PrimaryKey(autoGenerate = true) val id: Int = 0, val name: String, val phone: String, val email: String, val sexo: String? = null, val isMonthly: Boolean = true, val monthlyFeeCents: Int? = null, val dueDay: Int? = null, val isActive: Boolean = true, val createdAt: Long, val updatedAt: Long )

package com.parkcontrol.features.monthlyCustomers.data.local.mapper

import com.parkcontrol.features.monthlyCustomers.data.local.entity.CustomerVehicleEntity
import com.parkcontrol.features.monthlyCustomers.data.local.entity.MonthlyCustomerEntity
import com.parkcontrol.features.monthlyCustomers.data.local.entity.MonthlyCustomerWithPlates
import com.parkcontrol.features.monthlyCustomers.domain.model.MonthlyCustomer

fun MonthlyCustomerWithPlates.toDomain(): MonthlyCustomer {
    val orderedVehicles = vehicles
        .sortedWith(compareByDescending<CustomerVehicleEntity> { it.isPrimary }.thenBy { it.id })
        .map { it.toDomain() }

    return MonthlyCustomer(
        id = customer.id,
        name = customer.name,
        phone = customer.phone,
        email = customer.email,
        isMonthly = customer.isMonthly,
        monthlyFeeCents = customer.monthlyFeeCents,
        dueDay = customer.dueDay,
        vehicles = orderedVehicles,
        isActive = customer.isActive,
        createdAt = customer.createdAt,
        updatedAt = customer.updatedAt
    )
}

fun MonthlyCustomer.toEntity(): MonthlyCustomerEntity {
    return MonthlyCustomerEntity(
        id = id,
        name = name,
        phone = phone,
        email = email,
        isMonthly = isMonthly,
        monthlyFeeCents = monthlyFeeCents,
        dueDay = dueDay,
        isActive = isActive,
        createdAt = createdAt,
        updatedAt = updatedAt
    )
}

fun List<MonthlyCustomerWithPlates>.toDomain(): List<MonthlyCustomer> {
    return this.map { it.toDomain() }
}

